with open('public/data/words.json') as f:
    data = json.load(f)

words = data['words'] if isinstance(data, dict) and 'words' in data else data

filled = 0
for w in words:
    if not isinstance(w, dict):
        continue
    word = w.get('word', '')
    phrases = w.get('phrases', [])
    if not phrases and word in PHRASES:
        w['phrases'] = PHRASES[word]
        filled += 1

print(f'W92 补短语: {filled} 词')

with open('public/data/words.json', 'w') as f:
    json.dump(data, f, ensure_ascii=False, indent=2)

# 验证
with open('public/data/words.json') as f:
    data2 = json.load(f)
words2 = data2['words'] if isinstance(data2, dict) and 'words' in data2 else data2
